    }
    if (motivoPedido) return { finanzas_id: null, estado: 'sin_bloque', motivo: motivoPedido, huella: null, numeros: [], semanas: 12, resumen: null, declaradas: [] }
    return null
  } catch (x) { return null }
})()
const ctxPN = { identidad: identidadDeclarada(ficha, { primary_colors: (manual.identidad_del_manual || {}).primary_colors, typography: (manual.identidad_del_manual || {}).typography }), moneda: monedaDelCliente(ficha, manual), nombres_visibles: nombresVisibles(ficha) };
const material = Array.isArray(ent.material) ? ent.material : [];
const descartados = Array.isArray(ent.descartados) ? ent.descartados : [];
const referencia = String(ent.referencia || '');   // el documento v3, pegado entero
