const textoDeLosInsumos = [JSON.stringify(fichaSinInternos.ficha), JSON.stringify(manual), JSON.stringify(ent.material || []), JSON.stringify(ent.descartados || []), JSON.stringify(ent.hechos_del_dueno || [])].join('\n');
const PROTEGIDAS = personasAProteger(ficha, textoDeLosInsumos, ctxPN.nombres_visibles);
