  var personas = _persona(sinUrls, _nombresDePersonas(ctx && ctx.personas, ctx && ctx.nombre_cliente))
  if (personas.length) fugas = fugas.concat(personas.slice(0, 3).map(function (n) { return 'nombre de una persona: ' + n }))
