  texto: texto,
  caracteres: texto.length,
  registro_revisado: revisionDeRegistro ? { registro: registroDelPlan, corregidas: revisionDeRegistro.corregidas.length, formas_corregidas: revisionDeRegistro.corregidas.map((x) => x.antes + ' → ' + x.despues).slice(0, 40), restantes: revisionDeRegistro.restantes } : null,
  calentamiento_quitado: sinCalentamiento.quitado || null,
  chequeo_del_plan: chequeoDelPlan,
  registro_interno: registroInterno,
  estado_del_plan: estadoDelPlan,
  con_pendientes: estadoDelPlan === 'con_pendientes',
  pendientes: pendientes,
  descartados_declarados: llego && Array.isArray(descartados) ? descartados.length : null,
  no_se_busco_interno: llego && Array.isArray(descartados) ? descartados : null,
  client_id: cid,
  client_name: cnom,
  motivo: llego ? null
    : 'la vuelta del redactor NO llegó · se agotó la espera · el plan puede haberse escrito igual y estar en el corredor · NO se da por exitosa',
} }];

// [PLANEACIÓN] ② GUARDA · sin referencia del producto se DETIENE · E16 · 2026-09-12
//
// 🔴 POR QUÉ ES UN NODO APARTE Y NO UNA LÍNEA ADENTRO DEL REDACTOR:
// el nodo `Redactor (B4)` tiene `onError: continueRegularOutput` — se traga sus
// propios errores. Un `throw` adentro NO detiene nada: la corrida seguiría hasta
// `Pedir el plan al redactor` y pagaría igual. Lo probé antes de publicarlo.
// Este nodo NO lleva `onError`: el que falla acá, detiene. Mismo patrón que la
// guarda del manual de marca, que es la otra cosa sin la cual no hay plan.
//
// ⚠️ NO CONTRADICE LA REGLA 0 DE EMILIO: un dato del NEGOCIO que falta (precio,
// costos, presupuesto) NO bloquea · se declara el hueco y el plan sale igual.
// Esto es el CONTRATO del producto: sin las ocho secciones no hay plan, hay
// redacción libre. Material faltante ⇒ se declara. Escritura rota ⇒ se detiene.
const REFERENCIA_MINIMA = 2000;
const entrada = ($input.first() && $input.first().json) || {};
const ref = String(entrada.referencia || '').trim();
const loQueDiceElPuente = String((entrada.puente_declara || {}).referencia || 'el puente no declaró nada');
if (ref.length < REFERENCIA_MINIMA) {
  throw new Error('PLANEACION_REFERENCIA_VACIA · el documento de referencia del producto llegó con '
    + ref.length + ' caracteres (mínimo ' + REFERENCIA_MINIMA + ') · sin las ocho secciones el plan no'
    + ' tiene estructura pedida y el redactor escribiría a criterio propio · la corrida SE DETIENE'
    + ' antes de invocar y NO se gasta · lo que dice el puente: ' + loQueDiceElPuente);
}
// 🟢 pasa tal cual · una guarda no transforma lo que deja pasar
return $input.all();

// Si la puerta no acepto el sobre, NO se calla. Mismo patron que el resto de la casa (E101):
// una nota perdida se DECLARA, no se traga. No corrige nada.
const r = $input.first().json || {};
const cuerpo = r.body || r;
const ok = !!cuerpo && (cuerpo.ok === true || cuerpo.kind === 'accepted' || cuerpo.kind === 'duplicate');
if (!ok) {
  return [{ json: { _nota_perdida: true, motivo: 'SOBRE_DEL_BRIEF_NO_ACEPTADO',
    detalle: (cuerpo && (cuerpo.detail || cuerpo.code)) || 'sin detalle',
    flujo: 'X9F0zp6LQ2xGEYVS', nodo: "BRIEF · sobre · pedir el parte a la sala (E-brief · CC#2)" } }];
}
return [{ json: { _nota_perdida: false, sobre: cuerpo.kind || 'accepted', event_id: cuerpo.event_id || null } }];

// ⑤ SECO · LO QUE SE HABRÍA ESCRITO · CC#1 · 2026-09-30. En modo seco NADA se escribe, ni se sube, ni se avisa: ni la tabla, ni Drive, ni la sala, ni el aviso, ni el parte.
// Llega hasta acá con el MISMO camino que el real (ficha · manual · brazos · junta · derivador · pedido al redactor · espera · vuelta) y aquí sólo se DECLARA lo que habría pasado.
const v = $input.first().json || {}
const sobre = $('Webhook · planeacion').first().json.body || {}
if (!v.llego_la_vuelta) {
  throw new Error('PLANEACION_SECO_SIN_VUELTA · en el ensayo la vuelta del redactor NO llegó (' + String(v.motivo || 'sin motivo') + ') · en modo real esto habría terminado en aviso, no en plan')
}
const texto = String(v.texto || '')
return [{
  json: {
    seco: true,
    escrituras_reales: 0,
    no_se_escribio_en: ['client_historical_outputs (Guardar el plan)', 'Drive (texto-a-drive)', 'la sala (SALA_CALLBACK_URL · cable de vuelta)', 'el parte del brief (sobre plan-listo)', '#alertas (avisos)'],
    dry_run_enviado_al_nodo_que_paga: true,
    client_id: v.client_id || sobre.client_id || null,
    la_vuelta_del_redactor: { llego: !!v.llego_la_vuelta, caracteres: v.caracteres, bloque_de_lo_que_no_se_busco: texto.indexOf('## Lo que NO se buscó y por qué') !== -1, descartados_declarados: v.descartados_declarados === undefined ? null : v.descartados_declarados },
    habria_guardado: { tabla: 'client_historical_outputs', output_type: 'campaign_plan_90d', status: 'draft', largo_del_plan: texto.length },
    habria_subido_a_drive: { nombre_de_cliente: v.client_name || null, largo_del_texto: texto.length },
    habria_avisado_a_la_sala: { event_type: 'run_completed', worker_name: 'planeacion' },
    forzar_recibido: sobre.forzar === true,
  },
}]

// ⓪ LA LLAVE · CC#2 · relevo 15 (2026-10-08) · mismo patrón que `zero-risk/brief` y `zero-risk/pieza` (lección E67).
// Este flujo GASTA (modelo, Apify, imagen o video) o PUBLICA hacia afuera (redes, correo). Por eso exige la llave de despacho del motor en la cabecera
// `x-sala-dispatch-key` (la misma `SALA_DISPATCH_KEY` del entorno de n8n; no se copia a ningún otro sitio) y, si falta, se DETIENE antes de tocar nada.
// Falla CERRADO: sin la llave en el entorno, el flujo queda cerrado. Los disparos con horario (cron) y las llamadas internas entre flujos no pasan por aquí.
const w = $input.first().json || {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}
const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) {
  throw new Error('FLUJO_CERRADO · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) en su entorno · este flujo gasta o publica y queda cerrado hasta que exista · E67.')
}
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) {
  throw new Error('FLUJO_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · este flujo gasta o publica y solo lo despierta la sala · E67.')
}
return $input.all()

// r78 · lo que dijo el dueño, entregado por la función compartida (no por casualidad del cerebro). Si la lectura FALLA, la corrida SE DETIENE: un fallo no se lee como «no dijo nada».
const base = $('② GUARDA · sin referencia del producto se DETIENE').first().json;
const d = $input.first().json || {};
if (d.ok !== true) {
  throw new Error('PLANEACION_SIN_LECTURA_DE_LO_DEL_DUENO · no se pudo leer lo que el dueño declaró (' + [d.error, d.detail].filter(Boolean).join(' · ') + ') · la corrida SE DETIENE antes de invocar y NO se gasta');
}
return [{ json: Object.assign({}, base, { hechos_del_dueno: Array.isArray(d.hechos) ? d.hechos : [] }), pairedItem: { item: 0 } }];

// r80 · el plan con marcas NO queda «listo» en silencio: una línea para quien administra la agencia, en la bandeja (qué falta). Sin marcas: no sale ningún elemento y la rama termina aquí.
const v = ($('Plan vigente').first().json.jef_vigente || $('¿Llegó la vuelta?').first().json);
if (!v.con_pendientes) return [];
let planId = null;
try { const g = $('Plan vigente').first().json; const gb = (g && g.body) ? g.body : g; const fila = Array.isArray(gb) ? gb[0] : gb; planId = (fila && fila.id) || null; } catch (x) { planId = null; }
const quien = String(v.client_name || 'el cliente');
const linea = ('Plan de 90 días de ' + quien + ' con pendientes: ' + String(v.pendientes || 'el chequeo marcó el plan')).slice(0, 480);
const cuerpo = {
  type: 'plan_con_pendientes',
  title: linea,
  client_id: v.client_id || null,
  priority: 'high',
  agent_name: 'planeacion',
  risk_type: 'strategic_decision',
  output_preview: linea,
  payload: { plan_id: planId, estado_del_plan: v.estado_del_plan, marcas: (v.chequeo_del_plan && v.chequeo_del_plan.marcas) || [], para_el_cliente: false },
};
if (planId && v.client_id) cuerpo.output_id = planId;
return [{ json: { cuerpo } }];

// r80 · si la bandeja NO recibió el aviso, la corrida sale en ERROR a la vista (el plan ya está guardado y entregado a la sala: esto va al final a propósito)
const r = $input.first().json || {};
const hay = r.id || (r.item && r.item.id) || (r.ok === true) || (r.data && r.data.id);
if (!hay) throw new Error('PLAN_CON_PENDIENTES_SIN_AVISO · la bandeja no recibió el aviso (' + JSON.stringify(r).slice(0, 300) + ') · el plan está guardado como «con pendientes»: avisar a mano');
return [{ json: { aviso_en_bandeja: true, respuesta: r } }];

// F4 v2.1 · arma la SEMILLA de la oficina con lo que el plan ya tiene en el paquete (resúmenes cortos; nada del expediente entero). Nunca lanza.
const body = ($('Webhook · planeacion').first().json.body || {})
const p = $('Unir lo del dueño al paquete').first().json || {}
const ficha = p.ficha && typeof p.ficha === "object" ? p.ficha : {}
const cfg = ficha.config && typeof ficha.config === "object" ? ficha.config : {}
const manual = p.manual && typeof p.manual === "object" ? p.manual : {}
const reg = (p.registro_del_manual || manual.registro_del_manual || {}).registro
const material = Array.isArray(p.material) ? p.material : []
const descartados = Array.isArray(p.descartados) ? p.descartados : []
const semilla = {
  rubro: ficha.industry || null, pais: ficha.country || null, moneda: cfg.moneda || cfg.currency || null,
  ficha_resumen: 'Rubro: ' + (ficha.industry || 'sin declarar') + '. País: ' + (ficha.country || 'sin declarar') + '.',
  manual_resumen: reg ? 'Registro del cliente: ' + reg + '.' : 'Sin registro declarado en el manual.',
  brazos_resumen: 'Material recolectado: ' + material.length + ' ítems; descartados: ' + descartados.length + '.',
  fecha: new Date(Date.now()).toISOString().slice(0, 10),
}
// plan v3: si el `dato.v1` llegó, la oficina recibe la SEMILLA COMPACTA (datos con procedencia; lo que no cupo, declarado) en vez de solo los resúmenes del paquete
let pv = null
try { const p = $('PV3 · paquete').first().json; if (p && p.plan_version === 'v3' && p.semilla && Array.isArray(p.semilla.datos)) pv = p } catch (x) { pv = null }
if (pv) {
  semilla.datos = pv.semilla.datos
  semilla.datos_omitidos = Number(pv.semilla.datos_omitidos) || 0
  if (pv.semilla.nota) semilla.brazos_resumen = String(pv.semilla.nota).slice(0, 1500)
  if (pv.dry_run === true) semilla.corrida_es_de_ensayo = true
}
return [{ json: { accion: 'abrir', client_id: String(body.client_id), dry_run: body.dry_run === true, semilla: semilla, t0: Date.now() } }]

// F4 v2.1 · a dónde sigue la conversación de la oficina. FALLA HACIA «sin números»: nada de lo que se interprete mal bloquea ni se lee como «firmado». Nunca lanza.
const PLAZO_MS = 900000
const MAX_PASOS = 40
const r = $input.first().json || {}
const b = r.body && typeof r.body === "object" ? r.body : {}
const http = Number(r.statusCode)
const vuelta = Number($runIndex) || 0
const t0 = Number($('FIN · armar la semilla').first().json.t0) || Date.now()
const pasado = Date.now() - t0
// vuelta 0 = la respuesta de «abrir»; las demás, la de «avanzar»
if (vuelta === 0) {
  if (http === 409) return [{ json: { fin: true, resultado: 'apagada' } }]
  if (!(http === 200 && typeof b.encargo_id === 'string' && b.encargo_id)) return [{ json: { fin: true, finanzas_motivo: 'sin_bloque', detalle: 'la oficina no abrió (HTTP ' + (Number.isFinite(http) ? http : 'sin respuesta') + ')' } }]
  return [{ json: { fin: false, encargo_id: b.encargo_id } }]
}
const id = $('FIN · decidir').first().json.encargo_id
if (!(http === 200)) return [{ json: { fin: true, encargo_id: id, finanzas_motivo: 'sin_bloque', detalle: 'la oficina dejó de contestar (HTTP ' + (Number.isFinite(http) ? http : 'sin respuesta') + ')' } }]
if (b.terminado === true) return [{ json: { fin: true, encargo_id: id, leer: true, estado: String(b.estado || '') } }]
if (pasado > PLAZO_MS || vuelta >= MAX_PASOS) return [{ json: { fin: true, encargo_id: id, finanzas_motivo: 'vencido', detalle: 'la oficina no terminó a tiempo' } }]
return [{ json: { fin: false, encargo_id: id } }]

// F4 v2.1 · copia el resultado de la oficina al sobre del plan: `finanzas_id` si hay tablero, y `finanzas_motivo` (lista cerrada) cuando no hay firma. Nunca lanza.
const dec = $('FIN · decidir').first().json || {}
const body = ($('Webhook · planeacion').first().json.body || {})
if (dec.resultado === 'apagada') return [{ json: { finanzas_id: null, finanzas_motivo: null } }]
if (dec.finanzas_motivo) return [{ json: { finanzas_id: null, finanzas_motivo: dec.finanzas_motivo } }]
let leido = null
try { leido = $('FIN · leer el encargo').first().json || null } catch (x) { leido = null }
const cuerpo = leido && leido.body && typeof leido.body === "object" ? leido.body : {}
if (!leido || Number(leido.statusCode) !== 200) return [{ json: { finanzas_id: null, finanzas_motivo: 'sin_bloque' } }]
const turnos = Array.isArray(cuerpo.turnos) ? cuerpo.turnos : []
const t = turnos.filter(function (x) { return x && x.paso === 'firma' })[0]
const salida = t && t.salida && typeof t.salida === 'object' ? t.salida : null
const estado = String(cuerpo.estado || dec.estado || '')
if (estado === 'cierre_por_tope') return [{ json: { finanzas_id: null, finanzas_motivo: 'vencido' } }]
if (!salida) return [{ json: { finanzas_id: null, finanzas_motivo: estado === 'fallido' ? 'sin_bloque' : 'sin_firma' } }]
const MAPA = { sin_base: 'sin_referencia', sin_referencia: 'sin_referencia', sin_pauta: 'sin_pauta', sin_bloque: 'sin_bloque' }
if (salida.estado === 'sin_bloque') return [{ json: { finanzas_id: null, finanzas_motivo: MAPA[salida.motivo] || 'sin_bloque' } }]
const id = typeof salida.finanzas_id === 'string' && salida.finanzas_id ? salida.finanzas_id : null
// un ensayo (dry_run) no guarda tablero: no hay nada que leer ni firmar
if (!id) return [{ json: { finanzas_id: null, finanzas_motivo: 'sin_firma' } }]
if (salida.estado === 'firmado') return [{ json: { finanzas_id: id, finanzas_motivo: null } }]
return [{ json: { finanzas_id: id, finanzas_motivo: estado === 'sin_acuerdo' || salida.sin_acuerdo === true ? 'sin_acuerdo' : 'sin_firma' } }]

// F4 v2.1 · devuelve el paquete ORIGINAL. Si la oficina conducida por el plan dejó un resultado, lo agrega como `finanzas_efectivo`; si no, el paquete sale INTACTO (idéntico a hoy).
const paquete = $('Unir lo del dueño al paquete').all()
let ef = null
try { const c = $('FIN · cerrar la oficina').first().json; if (c && (c.finanzas_id || c.finanzas_motivo)) ef = { finanzas_id: c.finanzas_id || null, finanzas_motivo: c.finanzas_motivo || null } } catch (x) { ef = null }
if (!ef) return paquete
return paquete.map(function (i) { return { json: Object.assign({}, i.json, { finanzas_efectivo: ef }), pairedItem: i.pairedItem } })

// V9 · la respuesta del pre-vuelo → a dónde sigue la ejecución. FALLA CERRADO: lo que no se entiende NUNCA es «seguir».
const MAX_VUELTAS = 14
const r = $input.first().json || {}
const cuerpo = r.body && typeof r.body === "object" ? r.body : {}
const http = Number(r.statusCode)
const vuelta = Number($runIndex) || 0
const base = { vuelta: vuelta, http: Number.isFinite(http) ? http : null }
// sin respuesta, o una caída del servicio (5xx sin decisión): se reintenta unas veces y luego PARA
if (!Number.isFinite(http) || (http >= 500 && !cuerpo.decision) || (http === 0)) {
  if (vuelta + 1 < 3) return [{ json: Object.assign({ ruta: "esperar", motivo: "el pre-vuelo no contestó (se reintenta)" }, base) }]
  return [{ json: Object.assign({ ruta: "parar", decision: "no_corre", motivo: "prevuelo_sin_respuesta", detalle: "el pre-vuelo no contestó en 3 intentos: no se corrió nada y no se gastó nada" }, base) }]
}
const d = String(cuerpo.decision || "")
const comun = { decision: d || null, motivo: cuerpo.motivo || null, detalle: cuerpo.detalle || null, corrida: cuerpo.corrida || null, dry_run: cuerpo.dry_run === true, relleno_permitido: cuerpo.relleno_permitido === true, huecos_tipos: Array.isArray(cuerpo.huecos_tipos) ? cuerpo.huecos_tipos : [], declara: Array.isArray(cuerpo.declara) ? cuerpo.declara : [], sube_la_ficha_a: cuerpo.sube_la_ficha_a == null ? null : cuerpo.sube_la_ficha_a }
if (http === 200 && (d === "correr" || d === "correr_con_lo_del_alta")) return [{ json: Object.assign({ ruta: "seguir" }, comun, base) }]
if (http === 200 && d === "esperar") {
  if (vuelta + 1 >= MAX_VUELTAS) return [{ json: Object.assign({ ruta: "parar" }, comun, base, { decision: "no_corre", motivo: "espera_excedida", detalle: "el flujo esperó más vueltas de las posibles; la corrida la libera el barrido" }) }]
  return [{ json: Object.assign({ ruta: "esperar", reintentar_en_s: 300 }, comun, base) }]
}
// ya_en_marcha / terminada: otro re-disparo lleva la corrida o ya terminó → esta ejecución NO hace nada (un solo plan)
return [{ json: Object.assign({ ruta: "parar" }, comun, base, { decision: d || "no_corre", motivo: comun.motivo || ("http_" + http) }) }]

// V9 · el cable de vuelta NO puede ser mudo (mismo criterio que «Cable · ¿volvió? · repetida»): si la sala lo despachó y no se enteró, falla RUIDOSA.
const r = $input.first().json || {}
const volvio = r.ok === true
let corr = null
try { corr = ($('Webhook · planeacion').first().json.body || {})._sala_correlation_id || null } catch (e) { corr = null }
if (corr && !volvio) {
  throw new Error('CABLE_DE_VUELTA_MUDO · la sala NO se entero de que la corrida no corrio · codigo ' + String(r.code || r.error || 'sin codigo'))
}
return [{ json: { cierre: 'no_corrio_prevuelo', vuelta_ok: volvio, vuelta_detalle: volvio ? (r.event_id || 'sin event_id') : (r.code || r.detail || r.error || 'sin respuesta de la sala'), despachado_por_la_sala: !!corr } }]

// V9 · al TERMINAR la corrida (plan entregado, o «repetida» ya sin gasto) se cierra la fila de `plan_corridas`. Si V9 no actuó (sin `plan_v3`), no hace nada.
const sobre = ($('Webhook · planeacion').first().json.body || {})
const pide = sobre.plan_v3 === true && typeof sobre.corrida === "string" && sobre.corrida.length > 0 && typeof sobre.client_id === "string" && sobre.client_id.length > 0
if (!pide) return [{ json: { aplica: false } }]
let repetida = false
try { $('Cable · ¿volvió? · repetida').first(); repetida = true } catch (e) { repetida = false }
return [{ json: { aplica: true, cuerpo: {
  accion: "cerrar", client_id: sobre.client_id, corrida: sobre.corrida,
  estado: repetida ? "fallida" : "hecha",
  motivo: repetida ? "el cliente ya tenía un plan (corrida repetida): no se gastó" : "plan entregado",
} } }]

// V9 · el pre-vuelo NO autorizó el relleno (sin «cerebro listo» leído en ESTA corrida): la rama de Apify NO llama a nada. Sale como una rama APAGADA (pasamanos): la junta la declara.
let d = {}
try { d = $('V9 · decidir').first().json || {} } catch (e) { d = {} }
const elegidos = $input.first().json || {}
const pedidos = Array.isArray(elegidos.pedidos) ? elegidos.pedidos : []
const huecos = Array.isArray(d.huecos_tipos) ? d.huecos_tipos : []
const motivo = "sin_relleno: el pre-vuelo no autorizó el relleno (no hubo «cerebro listo» en esta corrida) · el Servicio de Apify NO se llamó" + (huecos.length ? " · tipos que el cerebro declaró sin: " + huecos.join(", ") : "")
return [{ json: { pedidos: [], descartados: pedidos.filter((p) => p && p.brazo === 'apify').map((p) => ({ objetivo: p.objetivo, motivo: motivo })) } }]

// PLAN v3 · arma el pedido del `dato.v1`: el cliente y el ensayo del sobre, y lo que V9 decidió sobre el relleno. Nunca lanza.
const body = ($('Webhook · planeacion').first().json.body || {})
let v9 = {}
try { v9 = $('V9 · decidir').first().json || {} } catch (x) { v9 = {} }
// `dry_run` AUSENTE = real (como la sala): no se inventa; un valor no booleano viaja tal cual y la ruta lo rechaza
const salida = { client_id: String(body.client_id), relleno_permitido: v9.relleno_permitido === true, huecos_tipos: Array.isArray(v9.huecos_tipos) ? v9.huecos_tipos : [] }
if (body.dry_run !== undefined) salida.dry_run = body.dry_run
return [{ json: salida }]

// PLAN v3 · lo que contestó la ruta. Lo que no se entiende NO activa el plan v3: «Redactor (B4)» queda como hoy. Nunca lanza.
const r = $input.first().json || {}
const b = r.body && typeof r.body === "object" && !Array.isArray(r.body) ? r.body : {}
const http = Number(r.statusCode)
