  var corregidas = []
  if (registro !== 'tuteo') return { texto: entrada, corregidas: corregidas, restantes: [] }
  // lo citado no se toca: «…», `…` y direcciones
  var partes = entrada.split(/(«[^»]*»|`[^`]*`|https?:\/\/\S+)/)
