// ── lo que la tabla NO conoce: SOLO se marca, nunca se reescribe (ronda 68 · seguimiento)
// Una lista de excepciones evita marcar palabras corrientes que terminan igual (más, país, cafés, está, modelo…).
function _conjunto(lista) { var o = {}; lista.split(/\s+/).forEach(function (w) { if (w) o[w] = true }); return o }
var _EXC_ACENTUADAS = _conjunto('más además jamás después país atrás detrás quizás demás compás anís cafés bebés papás mamás sofás tés canapés purés comités rosés interés inglés francés portugués holandés japonés irlandés danés cortés revés través marqués ananás estés estás aguarrás')
var _EXC_FINAL_ACENTUADO = _conjunto('está será hará dará podrá tendrá vendrá saldrá valdrá pondrá habrá cabrá querrá sabrá allá acá papá mamá sofá maná ananá café bebé canapé comité rosé puré bidé jabalí esquí rubí bisturí maní')
// r78 · tuteo esdrújulo con clítico (escríbenos, llámanos): la sílaba acentuada va ANTES de la consonante + vocal + clítico; el voseo («miráme», «decímelo») no
var _ESDRUJULA_DE_TUTEO = /[áéíóú][^aeiouáéíóú]{1,3}[ae](nos|les|los|las|se)$/
var _EXC_CLITICO = _conjunto('telenovela aguacate chocolate paralelo disparate cancela cazuela mandela escalera consuelo abuelo modelo anhelo aleluya nacela parcela novela vitela tutela cuchilla bolsillo semilla')
var _CLITICOS_DE_VOS = /^(\p{L}{3,})(ale|ele|ile|ame|eme|ime|ate|ete|ite|alo|elo|ilo|ala|ela|ila|alas|elas|alos|elos|anos|enos|inos)$/u

/** formas que PARECEN voseo y no están en la tabla: acabados -ás/-és/-ís, imperativos en -á/-é/-í al arrancar una frase y con clítico (preguntale, dame…). Devuelve las formas tal como están escritas. */
function voseoDesconocido(texto) {
  var sin = String(texto ?? '').replace(/«[^»]*»|`[^`]*`|https?:\/\/\S+/g, ' ')
  var hallados = [], vistos = {}
  var re = /(^|[^\p{L}\p{N}_])(\p{L}+)(?![\p{L}\p{N}_])/gu
  var m
  while ((m = re.exec(sin)) !== null) {
    var palabra = m[2], k = palabra.toLowerCase()
    if (Object.prototype.hasOwnProperty.call(_VOS_A_TU, k)) continue // ya las cubren la corrección y formasDeVoseo («sos»/«SOS» está en la tabla; «vos» no cumple ninguna regla de abajo)
    var posImperativa = _enPosicionImperativa(sin.slice(0, m.index + m[1].length))
    var marca = false
    if (/^\p{L}{2,}(ás|és|ís)$/u.test(k)) marca = !_EXC_ACENTUADAS[k] && !/(ar|er|ir|dr|br|rr)ás$/.test(k) // futuros en -rás (tendrás, harás) son tuteo
    else if (posImperativa && !_EXC_FINAL_ACENTUADO[k]) {
      if (/([bcdfghjklmnñpqrstvwxyz]|[iu])á$/.test(k)) marca = k.length >= 5 && !/(ar|er|ir)á$/.test(k)
      else if (/[bcdfghjklmnñpqrstvwxyz]é$/.test(k)) marca = k.length >= 5
      else if (/[bcdfghjklmnñpqrstvwxyz]í$/.test(k)) marca = k.length >= 6
      else if (k.length >= 9 && _CLITICOS_DE_VOS.test(k)) marca = !_EXC_CLITICO[k] && !_ESDRUJULA_DE_TUTEO.test(k)
    }
    if (marca && !vistos[k]) { vistos[k] = true; hallados.push(palabra) }
  }
  return hallados
}

/** las formas de voseo que siguen en el texto (fuera de lo citado), para marcar lo que no se pudo corregir */
function formasDeVoseo(texto) {
  var sin = String(texto).replace(/«[^»]*»|`[^`]*`/g, ' ')
  var hallados = {}
  var re = /(^|[^\p{L}\p{N}_])(\p{L}+)(?![\p{L}\p{N}_])/gu
  var m
  while ((m = re.exec(sin)) !== null) {
    var k = m[2].toLowerCase()
    if (k === 'vos' || (Object.prototype.hasOwnProperty.call(_VOS_A_TU, k) && m[2] !== 'SOS' && !_VOS_AMBIGUO_CON_PASADO(k))) hallados[k] = (hallados[k] || 0) + 1
  }
  return Object.keys(hallados).map(function (k) { return k + (hallados[k] > 1 ? ' ×' + hallados[k] : '') })
}

/** lo que el sistema escribe al final del plan cuando algo no cuadra (nada si todo está bien) */
function bloqueDeRevisionDeRegistro(r, registro) {
  if (!r || (!r.restantes.length && registro === 'tuteo')) return ''
  if (registro === 'tuteo') return '\n\n## Revisión del registro (la hace el sistema)\n- Quedan formas de voseo (o que lo parecen) que no se corrigieron solas: ' + r.restantes.join(', ') + '. El registro de la marca es tuteo: revisar a mano.'
  return ''
}

/**
 * QUITAR LA FRASE DE CALENTAMIENTO DEL MODELO (ronda 73) · texto plano apto para pegar en un nodo Code de n8n (sin require/import/export).
 * Es de forma GENERAL: sirve a cualquier agente que entregue un documento (plan, manual, informe…); no sabe de qué cliente, rubro ni documento se trata.
 *
 * Qué es: el modelo suele abrir con una frase PARA EL USUARIO («Voy a escribir el plan…», «Aquí tienes el informe:», «Claro, …») y una raya `---` antes del documento.
 * Esa frase no es parte del documento: no debe guardarse, ni subirse a Drive, ni leerla el brief.
 * Regla (conservadora: ante la duda NO se toca): se quita el bloque inicial SOLO si
 *   1. el texto NO arranca ya en un título de markdown,
 *   2. el bloque son 1–3 párrafos cortos, sin viñetas ni títulos ni tablas,
 *   3. alguno de esos párrafos habla EN PRIMERA PERSONA o al lector como el que acompaña una entrega («Voy a…», «Aquí tienes…», «A continuación…», «Claro…»),
 *   4. y lo que sigue empieza en un título de markdown (opcionalmente tras una raya `---`): sin documento detrás, no se quita nada.
 * Devuelve { texto, quitado } · idempotente.
 */
function quitarCalentamiento(entrada) {
  var original = String(entrada === undefined || entrada === null ? '' : entrada)
  var s = original.replace(/^﻿/, '').replace(/^\s+/, '')
  if (!s || /^#{1,6}\s/.test(s)) return { texto: original, quitado: '' }
  // el primer título del documento
  var m = /(^|\n)(#{1,6}[ \t]+\S)/.exec(s)
  if (!m) return { texto: original, quitado: '' }
  var posTitulo = m.index + m[1].length
  var antes = s.slice(0, posTitulo)
  // la raya de separación (---, ***, ___) justo antes del título no es documento
  var bloque = antes.replace(/\n[ \t]*([-*_])(?:[ \t]*\1){2,}[ \t]*\n*$/, '\n').replace(/\s+$/, '')
  if (!bloque) return { texto: original, quitado: '' }
  var lineas = bloque.split(/\n/)
  // sin viñetas, tablas, títulos, código ni citas: es una frase de acompañamiento, no contenido
  for (var i = 0; i < lineas.length; i++) {
    if (/^\s*([-*+•]\s|\d+[.)]\s|\||```|>|#)/.test(lineas[i])) return { texto: original, quitado: '' }
  }
  var parrafos = bloque.split(/\n\s*\n/).map(function (p) { return p.trim() }).filter(function (p) { return p && !/^([-*_])(?:\s*\1){2,}$/.test(p) })
  if (parrafos.length < 1 || parrafos.length > 3) return { texto: original, quitado: '' }
  for (var k = 0; k < parrafos.length; k++) if (parrafos[k].length > 320) return { texto: original, quitado: '' }
  var acompana = /^(?:claro|perfecto|entendido|listo|de acuerdo|por supuesto|excelente|muy bien|vale|ok|okay|sure|certainly|of course|got it|absolutely)\b|^(?:voy a|vamos a|procedo a|empiezo|comienzo|empecemos|a continuaci[oó]n|aqu[ií] (?:est[aá]|tienes|tiene|va|te dejo|te entrego|presento|est[aá]n)|te (?:entrego|dejo|presento|comparto)|le (?:entrego|dejo|presento)|ahora (?:voy|escribo|redacto|armo)|con (?:toda )?la (?:evidencia|informaci[oó]n)|tengo (?:todo|toda|lo necesario|la evidencia)|ya tengo|habiendo (?:le[ií]do|revisado)|bas[aá]ndome|seg[uú]n lo (?:pedido|solicitado)|i(?:'| wi)ll\b|i(?:'|’)m going to|here(?:'|’)s|here is|let me|below is)/i
  var habla = false
  for (var j = 0; j < parrafos.length; j++) if (acompana.test(parrafos[j].replace(/^[*_>\s]+/, ''))) habla = true
  if (!habla) return { texto: original, quitado: '' }
  return { texto: s.slice(posTitulo), quitado: bloque }
}

/**
 * EL PLAN DE 90 DÍAS A PRIMER NIVEL · v2 AGNÓSTICA (ronda 73) · texto plano apto para pegar en los nodos Code de n8n (sin require/import/export; estilo `var` + `function`).
 * Lo usan «Redactor (B4)» (la ficha limpia, el bloque de instrucciones, el contexto del chequeo) y «¿Llegó la vuelta?» (el chequeo del plan que volvió).
 *
 * 🔴 AGNÓSTICO: nada de esto sabe de un cliente, un lugar ni un rubro. Todo sale de la ficha, el manual, el cerebro y la investigación de CADA cliente.
 *    Los códigos de moneda y de país de abajo son DATOS (se amplían sin tocar la lógica). Una prueba hace grep de este archivo: 0 nombres, lugares ni rubros de un cliente.
 */

// ───────────────────────── 1 · LA FICHA QUE VE EL REDACTOR: sin topes ni reglas internas
// Claves de la ficha que son de la casa (topes de gasto, límites, llaves…): NO viajan al redactor, así que no pueden aparecer en el plan.
var CLAVES_INTERNAS = /spend|(^|_)cap(_|$)|tope|limit|quota|cuota|freno|budget_?rule|interno|internal|secret|token|api_?key|password|clave_?api/i

/** copia de la ficha sin las claves internas, en cualquier nivel · devuelve también las rutas quitadas (solo nombres de clave, nunca valores) */
function fichaLimpia(ficha) {
  var quitadas = []
  function limpiar(v, ruta) {
    if (Array.isArray(v)) return v.map(function (x, i) { return limpiar(x, ruta + '[' + i + ']') })
    if (v && typeof v === 'object') {
      var out = {}
      Object.keys(v).forEach(function (k) {
        if (CLAVES_INTERNAS.test(k)) { quitadas.push((ruta ? ruta + '.' : '') + k); return }
        out[k] = limpiar(v[k], (ruta ? ruta + '.' : '') + k)
      })
      return out
    }
    return v
  }
  return { ficha: limpiar(ficha && typeof ficha === 'object' ? ficha : {}, ''), quitadas: quitadas }
}

// ───────────────────────── 2 · LA IDENTIDAD VISUAL Y LA MONEDA: salen de la ficha y del manual
function _lista(v) {
  if (Array.isArray(v)) return v.reduce(function (a, x) { return a.concat(typeof x === 'string' ? [x] : (x && typeof x === 'object' ? _lista(x.nombre || x.name || x.hex || x.valor || x.value || []) : [])) }, [])
  if (typeof v === 'string') return [v]
  return []
}
// solo los colores de seis dígitos (los de tres se confunden con una etiqueta o un número de punto)
function _hexes(texto) { return (String(texto == null ? '' : texto).match(/#[0-9a-fA-F]{6}\b/g) || []).map(function (h) { return h.toLowerCase() }) }

/** colores y tipografías declarados: la unión de las columnas de la ficha y las del manual (+ lo que el texto del manual nombra como tipografía) */
function identidadDeclarada(ficha, manual) {
  var f = ficha || {}, m = manual || {}
  var colores = {}, fuentes = {}
  _lista(f.brand_colors).concat(_lista(m.primary_colors)).forEach(function (c) { _hexes(c).forEach(function (h) { colores[h] = true }) })
  _hexes(typeof m.content_text === 'string' ? m.content_text : '').forEach(function (h) { colores[h] = true })
  _lista(f.brand_fonts).concat(_lista(m.typography)).forEach(function (t) { if (String(t).trim()) fuentes[String(t).trim().toLowerCase()] = String(t).trim() })
  if (typeof m.content_text === 'string') {
    try {
      var d = JSON.parse(m.content_text); d = d && d.brand_book_draft ? d.brand_book_draft : d
      ;_lista(d && (d.tipografias || d.typography)).forEach(function (t) { if (String(t).trim()) fuentes[String(t).trim().toLowerCase()] = String(t).trim() })
    } catch (e) { /* ilegible: se ignora, no se inventa */ }
  }
