    cola.split(/,| y | e |·|\/|;/).forEach(function (n) {
      var nombre = n.replace(/[()«»"*_]/g, '').trim()
      if (/^[A-ZÁÉÍÓÚÑ][\w'’ ]{2,30}$/.test(nombre) && nombre.split(' ').length <= 4 && !declaradosF[nombre.toLowerCase()] && fuera.indexOf(nombre) < 0) fuera.push(nombre)
    })
  })
  if (fuera.length) marcas.push({ codigo: 'P5', que: 'el plan cita colores o tipografías que el manual y la ficha no declaran', ejemplos: fuera.slice(0, 6) })

  // P6 · moneda distinta de la declarada (sin moneda declarada no se puede comprobar: se dice en el contexto, no se marca)
  if (mo.codigo) {
    var otras = []
    ;(t.match(/\b(?:USD|EUR|GBP|CAD|MXN|COP|PEN|ARS|CLP|UYU|BOB|PYG|BRL|GTQ|CRC|DOP|PAB)\b/g) || []).forEach(function (c) { if (c !== mo.codigo && otras.indexOf(c) < 0) otras.push(c) })
    if (mo.codigo !== 'EUR' && /€/.test(t)) otras.push('€')
    if (mo.codigo !== 'GBP' && /£/.test(t)) otras.push('£')
    if (otras.length) marcas.push({ codigo: 'P6', que: 'el plan usa una moneda distinta de la declarada (' + mo.codigo + ')', ejemplos: otras })
  }
  // P7 · el plan dice QUIÉN dio un dato (el dueño) o que una instrucción «manda»: eso es interno, el dato se dice como hecho
  var fugas = _ejemplos(t, RE_FUGA_DEL_DUENO, 3).concat(_ejemplos(t, RE_DICHO_POR_EL_DUENO, 3), _ejemplos(t, RE_PERSONA_CON_ROL, 3))
  var personas = _persona(sinUrls, _nombresDePersonas(ctx && ctx.personas, ctx && ctx.nombre_cliente))
  if (personas.length) fugas = fugas.concat(personas.slice(0, 3).map(function (n) { return 'nombre de una persona: ' + n }))
  if (fugas.length) marcas.push({ codigo: 'P7', que: 'el plan dice quién dio un dato, nombra a una persona del equipo o del dueño, o dice que una instrucción manda sobre otra fuente (eso es interno: el dato se dice como un hecho, sin nombres)', ejemplos: fugas })
  if (ctx && ctx.finanzas) { marcas = marcas.concat(revisarCifrasFinanzas(texto, ctx.finanzas)) }
  // plan v3 · P10a–m contra la tabla `dato.v1`: las ALTAS marcan (el plan sale «con pendientes»); las LEVES van en `avisos_p10`. NUNCA bloquea. Sin `plan_v3` en el contexto: nada cambia.
  var _avisosP10 = []
  if (ctx && ctx.plan_v3 && Array.isArray(ctx.plan_v3.datos)) {
    try {
      p10Revisar(texto, ctx.plan_v3.datos, ctx.plan_v3.op || {}).forEach(function (m) {
        var f = { codigo: m.codigo, que: m.que, ejemplos: m.ejemplos || [] }
        if (m.severidad === 'alta') marcas.push(f); else _avisosP10.push(f)
      })
    } catch (x) { /* un fallo del chequeo nunca bloquea el plan ni lo marca */ }
  }
  var _r = { ok: marcas.length === 0, marcas: marcas }
  if (_avisosP10.length) _r.avisos_p10 = _avisosP10
  return _r
}

/** el bloque que el SISTEMA añade al final del plan cuando el chequeo marca algo · sin citar nada de lo marcado (el detalle va en la salida del nodo) */
function bloqueDeRevisionDelPlan(r) {
  if (!r || r.ok) return ''
  return '\n\n## Revisión del plan (la hace el sistema)\n- Antes de enviarlo al cliente hay que revisar: ' + r.marcas.map(function (m) { return m.que }).join(' · ') + '.'
}


// ── JEF · plan · evaluar · J7 · CC#1 · 2026-10-14 · cada versión que produjo la jefatura (B, C) se mide con LOS MISMOS chequeos por código de hoy, que son el módulo de arriba (copia EXACTA del de «¿Llegó la vuelta?»: una prueba compara la huella).
// Salida: evaluaciones { etiqueta, marcas, largo } y, por versión, el texto ya revisado (calentamiento fuera, registro corregido) que sería el que se guarde.
const entrada = $input.first().json || {}
const jef = entrada.jef || {}
const v = $('¿Llegó la vuelta?').first().json
const salida = jef.salida || {}
let registroDelPlan = null
try { registroDelPlan = $('Redactor (B4)').first().json.registro_usado.registro } catch (x) { registroDelPlan = null }
let contextoChequeo = null
try { contextoChequeo = $('Redactor (B4)').first().json.contexto_chequeo } catch (x) { contextoChequeo = null }
function procesar(textoCrudo) {
  const crudo = String(textoCrudo || '')
  const sinCalentamiento = quitarCalentamiento(crudo)
  const base = sinCalentamiento.texto.trim() ? sinCalentamiento.texto : crudo
  const reg = corregirRegistroDelPlan(base, registroDelPlan)
  const revisado = reg ? reg.texto : crudo
  const chequeo = revisarPlan(revisado, contextoChequeo)
  const pendientes = chequeo ? pendientesDelPlan(chequeo) : null
  const texto = revisado.replace(/\s+$/, '') + '\n'
  return { texto, caracteres: texto.length, chequeo_del_plan: chequeo, pendientes, estado_del_plan: pendientes ? 'con_pendientes' : 'sin_marcas', con_pendientes: !!pendientes, marcas: chequeo && Array.isArray(chequeo.marcas) ? chequeo.marcas.length : 0 }
}
const procesadas = {}
const evaluaciones = [{ etiqueta: 'A', marcas: v.chequeo_del_plan && Array.isArray(v.chequeo_del_plan.marcas) ? v.chequeo_del_plan.marcas.length : 0, largo: String(v.texto || '').length }]
for (const x of (Array.isArray(salida.versiones) ? salida.versiones : [])) {
  if (!x || (x.etiqueta !== 'B' && x.etiqueta !== 'C') || typeof x.texto !== 'string' || !x.texto.trim()) continue
  const p = procesar(x.texto)
  procesadas[x.etiqueta] = p
  evaluaciones.push({ etiqueta: x.etiqueta, marcas: p.marcas, largo: p.caracteres })
}
return [{ json: { jef, id_de_a: jef.id_de_a, client_id: jef.client_id, evaluaciones, procesadas } }]

// JEF · plan · armar la elección · J7 · CC#1 · 2026-10-14 · lo que le pide a la ruta `elegir_version`: las evaluaciones y las filas del plan que YA existen (para no duplicar: una hija por padre, G4/G7).
// Si las filas no se pudieron leer NO se elige ni se guarda nada (no se puede garantizar que no se duplique): A sigue vigente.
const CFG = {"tipo":"plan"}
const ev = $('JEF · plan · evaluar').first().json
const r = $input.first().json || {}
const filas = r.body
if (Number(r.statusCode) !== 200 || !Array.isArray(filas)) return [{ json: { ok: false, motivo: 'no se pudieron leer las filas del plan (HTTP ' + String(r.statusCode) + '): no se guarda ninguna versión' } }]
const existentes = filas.filter((f) => f && typeof f.id === 'string').map((f) => ({ id: f.id, version_de: f.provenance_tag && typeof f.provenance_tag.version_de === 'string' && f.provenance_tag.version_de ? f.provenance_tag.version_de : null }))
const tags = {}
for (const f of filas) if (f && typeof f.id === 'string' && f.provenance_tag && typeof f.provenance_tag === 'object') tags[f.id] = f.provenance_tag
return [{ json: { ok: true, cuerpo: { accion: 'elegir_version', revision_id: ev.jef.revision_id, evaluaciones: ev.evaluaciones, id_de_a: ev.id_de_a, existentes }, tags } }]

// JEF · plan · el plan de guardado · J7 · CC#1 · 2026-10-14 · lo que contestó `elegir_version`: qué versión se adopta, qué se guarda (B antes que C, sin duplicar) y qué se marca.
// Aquí no se escribe nada. Si no hay nada que guardar (se adoptó A, o ya existían las hijas) «Plan vigente» devuelve lo de hoy.
const CFG = {"tipo":"plan"}
const r = $input.first().json || {}
const b = r.body && typeof r.body === 'object' ? r.body : {}
const ev = $('JEF · plan · evaluar').first().json
const el = $('JEF · plan · armar la elección').first().json
const plan = b.plan_de_guardado && typeof b.plan_de_guardado === 'object' ? b.plan_de_guardado : {}
const guardar = Array.isArray(plan.guardar) ? plan.guardar.filter((g) => g && (g.etiqueta === 'B' || g.etiqueta === 'C') && ev.procesadas[g.etiqueta]) : []
return [{ json: { jef: ev.jef, id_de_a: ev.id_de_a, client_id: ev.client_id, procesadas: ev.procesadas, tags: el.tags, adoptada: b.adoptada || null, resultado: b.resultado || null, marcas: b.marcas || null, guardar, razones: Array.isArray(b.razones) ? b.razones : [], solo_en_la_traza: Array.isArray(plan.solo_en_la_traza) ? plan.solo_en_la_traza : [] } }]

// JEF · plan · algo falló · J7 · CC#1 · 2026-10-14 · cualquier paso de guardar una versión que no salió bien termina AQUÍ y sigue a «Plan vigente», que devuelve la última fila realmente guardada (o A).
// Nada se reintenta y nada se borra: lo ya guardado queda (con su rastro) y se dice qué falló. NO lanza.
const CFG = {"tipo":"plan"}
const r = $input.first().json || {}
const b = r.body && typeof r.body === 'object' ? r.body : {}
return [{ json: { fallo: true, http: Number.isFinite(Number(r.statusCode)) ? Number(r.statusCode) : null, detalle: String(b.error || b.detalle || (r.error && r.error.message) || 'sin detalle').slice(0, 300) } }]

// Plan vigente · J7 · CC#1 · 2026-10-14 · diseño v4 §5.1 · el plan que sigue por la cadena: la ÚLTIMA fila realmente guardada (C, si no B), y si no se guardó ninguna, A.
// Sin versión nueva devuelve EXACTAMENTE la salida de «Guardar el plan» (idéntico a hoy). Con una versión nueva devuelve su fila + `jef_vigente` (su texto y sus marcas, medidos con los mismos chequeos de hoy):
// los nodos de después (Drive, aviso, «BRIEF · sobre», «¿Salió el PDF?») leen `jef_vigente` si existe y, si no, lo de siempre.
const CFG = {"tipo":"plan"}
const orig = $('Guardar el plan').all()
let est = null
try { est = $('JEF · plan · el plan de guardado').first().json } catch (x) { est = null }
if (!est || !est.procesadas) return orig
let ultima = null, etiqueta = null
for (const S of ['B', 'C']) {
  try {
    const r = $('JEF · plan · guardar ' + S).first().json
    const row = Array.isArray(r.body) ? r.body[0] : null
    if ([200, 201].indexOf(Number(r.statusCode)) !== -1 && row && row.id) { ultima = row; etiqueta = S }
  } catch (x) { /* ese nodo no corrió */ }
}
if (!ultima || !est.procesadas[etiqueta]) return orig
const p = est.procesadas[etiqueta]
const vuelta = $('¿Llegó la vuelta?').first().json
return [{ json: { ...ultima, jef_vigente: { texto: p.texto, caracteres: p.caracteres, con_pendientes: p.con_pendientes, pendientes: p.pendientes, estado_del_plan: p.estado_del_plan, chequeo_del_plan: p.chequeo_del_plan, client_id: vuelta.client_id, client_name: vuelta.client_name, llego_la_vuelta: true, etiqueta } } }]

// JEF · plan · armar la marca · J7 · CC#1 · 2026-10-14 · R4 cerrado POR DISEÑO (firma A): si la revisión del plan NO terminó bien (se pasó el plazo, o cerró con desacuerdo / sin segunda mirada / por tope / fallida)
// el plan sigue su camino con su marca «revisión incompleta» — nunca se pierde y nunca se hace pasar por revisado. Cuelga de «Plan vigente» como una rama lateral: no cambia lo que reciben el PDF, el aviso ni el brief.
// Sin marca que poner (jefatura apagada, 409, error, revisión limpia) no devuelve ítems y la rama termina aquí: idéntico a hoy. La marca se escribe en el `provenance_tag` COMPLETO de la fila vigente (G5), nunca parcial.
const CFG = {"tipo":"plan"}
const pv = $input.first().json || {}
let jef = {}
try { jef = $('JEF · aplicar').first().json.jef || {} } catch (x) { jef = {} }
let resultado = null, motivo = null
if (jef.fase === 'plazo') { resultado = 'incompleta_por_plazo'; motivo = String(jef.motivo || 'se acabó el plazo de la revisión') }
else if (jef.fase === 'cerrada' && jef.salida && typeof jef.salida === 'object') {
  let r = String(jef.salida.resultado || '')
  // si hubo versiones nuevas, el resultado final (con_desacuerdo cuando no se adoptó la última) lo dijo `elegir_version`
  try { const est = $('JEF · plan · el plan de guardado').first().json; if (est && est.resultado) r = String(est.resultado) } catch (x) { /* no hubo elección */ }
  if (r && r !== 'limpia') resultado = r
}
if (!resultado) return []
const tag = pv.provenance_tag
if (typeof pv.id !== 'string' || !pv.id || !tag || typeof tag !== 'object' || Array.isArray(tag) || !Object.keys(tag).length) return []
if (tag.jefatura_marcas && tag.jefatura_marcas.resultado === resultado && tag.jefatura_marcas.revision_id === (jef.revision_id || null)) return []
let cliente = null
try { cliente = $('¿Llegó la vuelta?').first().json.client_name } catch (x) { cliente = null }
const jefatura_marcas = { resultado, revision_id: jef.revision_id || null, motivo, marcado_en: new Date().toISOString() }
const texto = ':warning: *Plan con revisión incompleta* — ' + String(cliente || 'el cliente') + '\n• la revisión de calidad terminó: `' + resultado + '`' + (motivo ? ' (' + motivo + ')' : '') + '\n• el plan SIGUE su camino (PDF y brief) marcado en su `provenance_tag.jefatura_marcas`; queda marcado para revisión'
return [{ json: { id: pv.id, cuerpo: { provenance_tag: Object.assign({}, tag, { jefatura_marcas }) }, texto, resultado } }]

// JEF · plan · armar S · J7 · CC#1 · 2026-10-14 · prepara guardar la versión S (B o C): su fila, su `provenance_tag` (lo calcula la RUTA con la fila de partida LEÍDA, nunca a mano) y a quién reemplaza.
// El padre de B es A; el de C es B (o A si B no pasó). Se lee el `provenance_tag` ACTUAL del padre (el de A viene de «Guardar el plan»; el de B, de lo que acaba de devolver su inserción).
const CFG = {"tipo":"plan","etiqueta":"B"}
const S = CFG.etiqueta
const est = $('JEF · plan · el plan de guardado').first().json
const g = est.guardar.find((x) => x.etiqueta === S)
const fila = (() => { const gg = $('Guardar el plan').first().json; const gb = gg && gg.body ? gg.body : gg; return Array.isArray(gb) ? gb[0] : gb })()
const insertada = (E) => { try { const r = $('JEF · plan · guardar ' + E).first().json; const row = Array.isArray(r.body) ? r.body[0] : null; return [200, 201].indexOf(Number(r.statusCode)) !== -1 && row && row.id ? row : null } catch (x) { return null } }
const padre = (() => {
  if (g.version_de === 'A') return { label: 'A', id: est.id_de_a, tag: fila.provenance_tag }
  const insB = insertada('B')
  if (insB) return { label: 'B', id: insB.id, tag: insB.provenance_tag }
  const reB = (est.guardar.find((x) => x.etiqueta === 'B') || {}).reutilizar_id
  return { label: 'B', id: reB || null, tag: reB ? est.tags[reB] : null }
})()
const p = est.procesadas[S]
const hoy = new Date().toISOString().slice(0, 10)
return [{ json: {
  padre,
  pedido_tag: { accion: 'provenance_de_version', provenance_tag: padre.tag, etiqueta: S, version: g.version, version_de: padre.id, jefatura_revision_id: est.jef.revision_id },
  fila_base: { client_id: est.client_id, title: 'Plan de 90 dias · ' + hoy + ' · versión ' + S, output_type: 'campaign_plan_90d', content: p.texto, content_text: p.texto, producing_agent: 'campaign-brief-agent', status: 'draft' },
  // lo que describe a ESTA versión y no a A (la fila hereda el resto del rastro de A)
  tag_propio: { caracteres: p.caracteres, estado_del_plan: p.estado_del_plan, pendientes: p.pendientes || null },
} }]

